import {translator,detectLanguage} from './i18n.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let {prefs,progress}=readPreferences({getItem:key=>localStorage.getItem(key)});
let lang=['en','de'].includes(prefs.lang)?prefs.lang:detectLanguage(),t=translator(lang),game=new Game(),startScreen=true,savedGame=null,savedSource=null,paused=false,speed=1,panel=null,selected=null,modal=null,buildType=null,winShown=false,overShown=false,confirmAction=null,lastSave=0,autosaveEnabled=false,audio=null,patientFilter='active',recruitRole='receptionist',staffView='hire',menuOpen=false,menuSection='rooms',editorRoomId=null,pendingEditRoomId=null,editorItemId=null;
const voice=new Announcer({onStatus(){if(renderer)renderUI();}});
function readStoredClinic(){savedGame=null;savedSource=null;try{savedSource=localStorage.getItem('scrubssitel-save');if(savedSource)savedGame=Game.restore(JSON.parse(savedSource));}catch{}}
readStoredClinic();
voice.reset(0);
const copy=(en,de)=>lang==='de'?de:en;
function patientPortrait(record){return characterPortrait({...record,child:record.age<16});}
function callText(call){return `${call.name}, ${copy('please come to','bitte zur')} ${label(ROOMS[call.roomType].name)}. ${copy('Room','Raum')} ${call.roomId}.`;}

const money=n=>new Intl.NumberFormat(lang==='de'?'de-DE':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const label=v=>tr(v,lang);
const icons={build:'▦',staff:'♟',research:'⚗',finances:'↗',patients:'▤',help:'?',settings:'⚙',pause:'Ⅱ',play:'▶',save:'↓',home:'⌂',close:'×'};
function btn(action,text,cls='',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function iconBtn(action,icon,title){return btn(action,icon,'icon-btn',`title="${escape(title)}" aria-label="${escape(title)}"`);}
function staffPortrait(person){return characterPortrait(person);}
function staffStatus(s){return copy(({travelWork:'Walking to work',travelBreak:'On the way to a break',break:s.breakRoomId?'Break in the lounge':'Standing break',cleaning:'Cleaning',idle:'Waiting for a workplace'})[s.state]||(s.breakPending?'Finishing before break':'At work'),({travelWork:'Auf dem Weg zur Arbeit',travelBreak:'Auf dem Weg zur Pause',break:s.breakRoomId?'Pause im Personalraum':'Stehpause',cleaning:'Reinigt die Klinik',idle:'Wartet auf Arbeitsplatz'})[s.state]||(s.breakPending?'Beendet Behandlung vor Pause':'Am Arbeitsplatz'));}
function avatar(s,size=''){return `<span class="avatar model-avatar ${size}"><img src="${staffPortrait(s)}" alt="${escape(s.name)}"/></span>`;}

function persistPrefs(){try{localStorage.setItem('scrubssitel-prefs',JSON.stringify(prefs));}catch{}}
function chime(type='tap'){if(!prefs.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const now=audio.currentTime;for(let i=0;i<(type==='cure'?3:1);i++){const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=(type==='error'?180:type==='cure'?523:440)*[1,1.25,1.5][i];g.gain.setValueAtTime(.045,now+i*.08);g.gain.exponentialRampToValueAtTime(.001,now+.14+i*.08);o.connect(g);g.connect(audio.destination);o.start(now+i*.08);o.stop(now+.16+i*.08);}}catch{}}
function notify(text,error=false){const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3200);chime(error?'error':'tap');}
const furnishingMessages={furnitureWall:['Place wall decorations on the back or left wall. Press R to switch walls.','Platziere Wanddeko an der hinteren oder linken Wand. Mit R wechselst du die Wand.'],furnitureDuplicate:['This room already has its treatment station. Build another room for a second one.','Dieser Raum hat bereits seinen Behandlungsplatz. Baue für einen zweiten einen weiteren Raum.'],furnitureNotEmpty:['The starter layout is available for an empty room.','Die Startvorlage ist für einen leeren Raum verfügbar.'],furnitureInvalid:['This furniture placement is invalid.','Diese Möbelplatzierung ist ungültig.'],furnitureRoom:['This furniture does not belong in this room.','Dieses Möbelstück passt nicht in diesen Raum.'],furnitureDoor:['Keep the doorway clear.','Halte den Türbereich frei.'],furnitureBlocked:['A seat or workstation cannot be reached from the door.','Ein Sitz- oder Arbeitsplatz ist von der Tür aus nicht erreichbar.'],furnitureBounds:['Keep the furniture inside this room.','Das Möbelstück muss innerhalb dieses Raums stehen.'],furnitureOverlap:['Another object is in the way.','Hier steht bereits ein anderes Möbelstück.'],furnitureAccess:['Keep the door and access to every seat and workstation clear.','Tür und Wege zu allen Sitz- und Arbeitsplätzen müssen frei bleiben.'],furnitureMissing:['Add the required furniture before finishing this room.','Ergänze die benötigten Möbel, bevor du den Raum fertigstellst.'],roomBusy:['This room is being cleared. Existing visits will finish first.','Dieser Raum wird freigemacht. Laufende Besuche werden zuerst beendet.'],roomEditing:['Finish furnishing this room before using it.','Richte diesen Raum fertig ein, bevor er genutzt werden kann.']};
function errorText(code){return furnishingMessages[code]?copy(...furnishingMessages[code]):t(code);}
function result(r,success){if(r?.error){notify(errorText(r.error),true);return false;}if(success)notify(success);renderUI();return true;}
function save(show=true){if(startScreen||modal?.type==='load')return false;try{localStorage.setItem('scrubssitel-save',JSON.stringify(game.snapshot()));localStorage.setItem('scrubssitel-progress',JSON.stringify(progress));if(show)notify(t('saved'));return true;}catch{if(show)notify(t('saveFailed'),true);return false;}}
function currentLevel(){return LEVELS[game.level-1];}
function enterRoomEditor(room){menuOpen=false;editorRoomId=room.id;pendingEditRoomId=null;editorItemId=null;buildType=null;panel='room-editor';selected={type:'room',id:room.id};renderer.selected=selected;renderer.buildType=null;renderer.startEditor(room.id);voice.suspend(true);renderUI();renderer.canvas.focus({preventScroll:true});}
function requestRoomEditor(id){const response=game.beginRoomEdit(id);if(response?.pending){pendingEditRoomId=id;selected={type:'room',id};renderer.selected=selected;panel='inspect';renderUI();return;}if(response?.error){result(response);return;}enterRoomEditor(response.room||game.room(id));}
function leaveRoomEditor(){const id=editorRoomId;editorRoomId=null;editorItemId=null;renderer.editor=null;renderer.drag=null;selected=id?{type:'room',id}:null;renderer.selected=selected;panel=id?'inspect':null;if(autosaveEnabled)save(false);renderUI();}
function clearEditor(){menuOpen=false;staffView='hire';editorRoomId=null;pendingEditRoomId=null;editorItemId=null;if(renderer)renderer.editor=null;}
function selectFurniture(id){const room=game.room(editorRoomId),item=room?.furniture.find(f=>f.id===id);if(!item)return;editorItemId=id;renderer.cancelFurnitureTool();renderer.editor.itemId=id;renderUI();}
function placeFurniture(item){if(editorRoomId===null)return;const response=item.id?game.moveFurniture(editorRoomId,item.id,item):game.addFurniture(editorRoomId,item.kind,item);if(response?.error){notify(errorText(response.error),true);return;}const moved=!!item.id;renderer.cancelFurnitureTool();editorItemId=moved?item.id:null;renderer.editor.itemId=editorItemId;if(autosaveEnabled)save(false);renderUI();}
function skipTutorialButton(){return btn('skip-tutorial',copy('Skip tutorial · keep playing freely','Tutorial überspringen · frei weiterspielen'),'tutorial-skip full');}
function furnitureName(kind){return kind==='seat'?copy('Seat (chair or sofa)','Sitzplatz (Stuhl oder Sofa)'):label(FURNITURE[kind]?.name)||kind;}
function furnitureImage(kind,roomType,rotation=0){return `<img src="${furniturePreview(kind,roomType,rotation)}" alt="" width="280" height="200" draggable="false"/>`;}
function furnitureCard(kind,spec,room,tool){
 const workstation=spec.ports?.some(p=>p.kind==='work'),placed=workstation?room.furniture.some(item=>FURNITURE[item.kind]?.ports?.some(p=>p.kind==='work')):!!spec.maxCount&&room.furniture.filter(item=>item.kind===kind).length>=spec.maxCount,unaffordable=game.cash<spec.cost,active=tool?.kind===kind&&!tool.id;
 const number=n=>new Intl.NumberFormat(lang==='de'?'de-DE':'en-US',{maximumFractionDigits:2}).format(n);
 return `<button class="furniture-card ${active?'selected':''}" data-action="furniture-buy" data-kind="${kind}" aria-pressed="${!!active}" title="${escape(label(spec.desc))}" ${placed||unaffordable?'disabled':''}><span class="furniture-preview" aria-hidden="true">${furnitureImage(kind,room.type)}</span><b>${escape(furnitureName(kind))}</b><span class="furniture-card-meta"><span class="furniture-price">${money(spec.cost)}</span><span class="furniture-size" title="${copy('Floor space in tiles','Grundfläche in Feldern')}">${number(spec.w)} × ${number(spec.h)}</span></span>${placed||unaffordable?`<small class="furniture-card-status">${placed?(workstation?copy('Workplace placed · remove it to swap','Arbeitsplatz vorhanden · zum Tauschen entfernen'):copy('Already placed','Bereits platziert')):copy('Insufficient funds','Zu wenig Geld')}</small>`:''}</button>`;
}
function editorPanel(){
 const room=game.room(editorRoomId);if(!room)return '';const status=layoutStatus(room),chosen=room.furniture.find(f=>f.id===editorItemId),tool=renderer.editor?.tool;
 const checks=requirements(room.type).map(req=>{const missing=status.missing.find(m=>m.kind===req.kind);return `<li class="${missing?'':'complete'}"><span>${missing?'○':'✓'}</span><b>${escape(req.kind==='counter'?copy('Reception desk (any style)','Empfangstresen (eine Variante)'):req.kind==='pharmacy'?copy('Treatment machine or pharmacy counter','Gerät oder Apothekentresen'):furnitureName(req.kind))}</b><small>${missing?missing.have:req.need} / ${req.need}</small></li>`;}).join('');
 return `<div class="panel-header"><div><small>${copy('FURNISH ROOM · GAME PAUSED','RAUM EINRICHTEN · SPIEL PAUSIERT')}</small><h2>${label(ROOMS[room.type].name)}</h2></div>${iconBtn('editor-close','×',copy('Save draft and close','Entwurf speichern und schließen'))}</div><div class="panel-scroll"><p class="editor-intro">${copy('Choose furniture, then click its place on the floor. Keep the door and the paths to seats and workstations clear.','Wähle ein Möbelstück und klicke auf seinen Platz am Boden. Halte Tür und Wege zu Sitz- und Arbeitsplätzen frei.')}</p><p class="furniture-access-legend"><i></i>${copy('Keep green access points clear','Grüne Zugangsmarker freihalten')}</p><ul class="furniture-requirements">${checks}</ul>${status.blocked?`<p class="editor-warning">${escape(errorText(status.blocked))}</p>`:''}
 ${tool?`<div class="furniture-tool"><b>${copy(tool.id?'Move':'Place',tool.id?'Verschieben':'Platzieren')}: ${escape(furnitureName(tool.kind))}</b><span>${FURNITURE[tool.kind].wall?copy('Snaps to the wall · R switches walls','Rastet an der Wand ein · R wechselt die Wand'):copy('Click the floor · arrows for fine adjustment','Auf den Boden klicken · Pfeiltasten für Feinschritte')}</span><div>${btn('furniture-rotate','↻ '+copy('Rotate','Drehen')+' · R','secondary')}${btn('furniture-cancel',copy('Cancel','Abbrechen')+' · Esc','text-button')}</div></div>`:chosen?`<div class="furniture-tool"><b>${escape(furnitureName(chosen.kind))}</b><div>${btn('furniture-move',copy('Move','Verschieben'),'secondary')}${btn('furniture-remove',copy('Remove','Entfernen')+' · +'+money(Math.round((chosen.paid||0)*.75)),'text-button danger')}</div></div>`:''}
 <h3 class="editor-section-title">${copy('Furniture catalog','Möbelkatalog')}</h3><div class="furniture-catalog">${Object.entries(FURNITURE).filter(([,f])=>f.rooms.includes(room.type)).map(([kind,f])=>furnitureCard(kind,f,room,tool)).join('')}</div>
 ${room.furniture.length?`<h3 class="editor-section-title">${copy('Placed furniture','Platzierte Möbel')}</h3><div class="furniture-placed">${room.furniture.map(f=>btn('furniture-select',`<span class="furniture-placed-preview" aria-hidden="true">${furnitureImage(f.kind,room.type,f.rotation)}</span><b>${escape(furnitureName(f.kind))}</b>`,f.id===editorItemId?'selected':'',`data-furniture="${escape(f.id)}"`)).join('')}</div>`:`<button class="text-button full template-button" data-action="furniture-template">${copy('Optional: use a starter layout','Optional: eine Startvorlage verwenden')}</button>`}</div><div class="editor-footer">${btn('editor-finish',copy('Finish room','Raum fertigstellen')+' ✓','primary full',status.ready?'':'disabled')}<small>${status.ready?copy('Equipment and access are ready.','Ausstattung und Zugang sind bereit.'):copy('Add all required furniture and keep access clear.','Pflichtmöbel ergänzen und die Zugänge freihalten.')}</small>${btn('editor-close',copy('Continue later','Später weiter'),'text-button full')}${game.mode==='tutorial'?skipTutorialButton():''}</div>`;
}
function renderMenu(){
 const root=$('#game-menu');if(!root)return;
 patchHTML(root,renderGameMenu(game,{open:menuOpen,section:menuSection,announcementsEnabled:voice.ready&&voice.enabled,helpers:{t,copy,label,btn,escape,money}}));
 root.classList.toggle('is-open',menuOpen);
 root.querySelector('.game-menu-toggle')?.setAttribute('data-caption',copy('Menu','Menü'));
 const shield=$('.menu-shield');if(menuOpen&&!shield){const el=document.createElement('button');el.className='menu-shield';el.dataset.action='menu-close';el.tabIndex=-1;el.setAttribute('aria-label',copy('Close menu','Menü schließen'));root.before(el);}else if(!menuOpen)shield?.remove();
 root.querySelector('[data-action="save"]')?.toggleAttribute('disabled',startScreen);
 root.querySelectorAll('[data-action="build"],[data-action="open-staff"],[data-action="panel"]').forEach(b=>{if(startScreen)b.disabled=true;});
}
function resetPanelScroll(){const el=$('#detail-panel .panel-scroll');if(el)el.scrollTop=0;}
function openStaff(role='receptionist',view='hire'){
 if(editorRoomId!==null)leaveRoomEditor();
 recruitRole=ROLES.includes(role)?role:'receptionist';staffView=view==='team'?'team':'hire';
 menuOpen=false;buildType=null;renderer.buildType=null;renderer.drag=null;selected=null;renderer.selected=null;panel='staff';renderUI();resetPanelScroll();
}
function languageOptions(){return `<label class="settings-row">${t('language')}<select id="language-select"><option value="auto" ${!prefs.lang||prefs.lang==='auto'?'selected':''}>${t('auto')}</option><option value="en" ${prefs.lang==='en'?'selected':''}>English</option><option value="de" ${prefs.lang==='de'?'selected':''}>Deutsch</option></select></label>`;}
function audioOptions(){return `<div class="settings-row"><span>${copy('Sound effects','Soundeffekte')}</span>${btn('sound',prefs.sound?t('on'):t('off'),'toggle '+(prefs.sound?'enabled':''),'aria-pressed="'+!!prefs.sound+'"')}</div><div class="settings-row"><span>${copy('Spoken patient calls','Gesprochene Patientenaufrufe')}</span>${btn('voice',voice.ready&&voice.enabled?t('on'):t('off'),'toggle '+(voice.ready&&voice.enabled?'enabled':''),'aria-pressed="'+!!(voice.ready&&voice.enabled)+'"')}</div><p class="panel-intro">${copy('Calls use the selected language. The next patient will be announced after you return to the clinic.','Aufrufe verwenden die gewählte Sprache. Der nächste Patient wird nach deiner Rückkehr in die Klinik ausgerufen.')}</p>`;}
function shell(){document.documentElement.lang=lang;document.title=`Funny Hospital · ${t('brandSub')}`;
 $('#app').innerHTML=`<header class="topbar"><a class="brand" href="#" aria-label="Funny Hospital"><span class="brand-mark">✚</span><span><strong>Funny Hospital<span class="brand-dot">.</span></strong><small>${t('brandSub')}</small></span></a><div class="vital-stats" id="vitals"></div></header>
 <div class="workbar"><div class="hospital-name"><span class="hospital-icon">⌂</span><span><b>${lang==='de'?'Klinik Miteinander':'Common Ground Hospital'}</b><small id="episode-label"></small></span></div><div class="time-controls" id="time-controls"></div></div>
 <main class="game-shell"><aside class="shift-sidebar" id="sidebar"></aside><section class="hospital-stage" aria-label="${t('floor')}"><div class="stage-topline"><span class="live-dot"></span><span id="stage-status">${t('planning')}</span><button class="clinic-open-button" data-action="open-clinic" id="clinic-open">${t('openClinic')} →</button></div><canvas id="hospital-canvas" tabindex="0" aria-label="${t('floor')}. ${t('buildHint')}"></canvas><div class="view-controls">${iconBtn('zoom-out','−',t('zoomOut'))}<span id="zoom-value">100%</span>${iconBtn('zoom-in','+',t('zoomIn'))}${iconBtn('center','⌖',t('resetView'))}${iconBtn('fullscreen','⛶',t('fullscreen'))}</div><div id="call-banner" class="call-banner" role="status" aria-live="polite"></div><div id="pause-label" class="pause-label" hidden>${t('paused')}</div><div id="stage-hint" class="stage-hint"></div><aside id="detail-panel" class="detail-panel" hidden></aside><div id="game-menu"></div></section></main>

 <div id="modal-root"></div><div id="toast" class="toast" role="status" aria-live="polite"></div><input type="file" accept="application/json,.json" id="import-file" hidden>`;
 renderer=new Renderer($('#hospital-canvas'),{onBuild(type,rect){if(startScreen||editorRoomId!==null)return;const response=game.addRoom(type,rect);if(result(response,t('built'))){enterRoomEditor(response.room);if(autosaveEnabled)save(false);}},onFurniturePlace:placeFurniture,onFurnitureToolChange(){renderUI();},onSelect(type,id){if(startScreen)return;if(editorRoomId!==null){const object=type==='object'?findObject(game,id):null;if(object?.roomId===editorRoomId&&object.furnitureId)selectFurniture(object.furnitureId);return;}selected=type?{type,id}:null;if(type==='patient')game.readChart(id);renderer.selected=selected;panel=type==='staff'?'staff':type?'inspect':null;if(type==='staff')staffView='team';menuOpen=false;renderUI();}});renderer.lang=lang;
 $('#import-file').addEventListener('change',importSave);renderUI();}
let renderer;
function renderStart(){
 document.body.classList.add('tutorial-mode');
 patchHTML($('#vitals'),`<div class="vital balance"><span class="stat-icon">＄</span><div><small>${t('startCapital')}</small><b>${money(50000)}</b></div></div>`);
 patchHTML($('#sidebar'),`<div class="start-intro"><span class="eyebrow">${t('guideClass')}</span><h1>${t('emptyStartTitle')}</h1><p>${t('emptyStartText')}</p><div class="start-actions">${btn('new-game',t('startGuided')+' →','primary full','data-mode="tutorial" data-level="1"')}${btn('new-game',copy('Play without tutorial','Ohne Tutorial spielen'),'secondary full','data-mode="sandbox" data-level="1"')}${savedGame?btn('resume-game',t('resumeClinic'),'secondary full'):''}${btn('episodes',t('otherModes'),'text-button full')}</div><ol class="start-steps">${[1,2,3].map(i=>`<li><b>${t('startStep'+i)}</b><span>${t('startStep'+i+'Text')}</span></li>`).join('')}</ol><p class="start-goal">${t('startGoal')}</p>${savedGame?`<div class="resume-card"><h2>${t('savedClinic')}</h2><p>${savedGame.rooms.length} ${t('rooms')} · ${money(savedGame.cash)}<br>${t('year')} ${savedGame.year} · ${t('month')} ${savedGame.month}</p>${btn('export',t('export'),'text-button full')}</div>`:savedSource?`<div class="resume-card"><p>${t('unreadableStartSave')}</p>${btn('export',t('export'),'secondary full')}</div>`:''}</div>`);
 $('#stage-status').textContent=t('planning');$('#stage-hint').textContent=t('startFloorHint');renderer.guideRect=null;
}
function renderUI(){
 document.body.classList.toggle('room-editor-open',editorRoomId!==null);
 renderMenu();
 document.body.classList.toggle('start-screen',startScreen);if(startScreen){renderStart();return;}
 if(editorRoomId!==null)panel='room-editor';
 $('#stage-status').textContent=editorRoomId!==null?copy('Furnishing · paused','Einrichten · pausiert'):t(game.admissionsOpen?'schedule':'planning');
 const focused=document.activeElement,focusAttrs=focused?.dataset?.action?Array.from(focused.attributes).filter(a=>a.name.startsWith('data-')).map(a=>`[${a.name}="${a.value}"]`).join(''):null;
 const active=game.patients.filter(p=>p.state!=='exit').length,guide=game.guide(),tutorial=game.mode==='tutorial';
 patchHTML($('#vitals'),`<div class="vital balance"><span class="stat-icon">＄</span><div><small>${t('cash')}</small><b class="${game.cash<0?'negative':''}">${money(game.cash)}</b></div></div><div class="vital"><span class="stat-icon star">${tutorial?'↗':'★'}</span><div><small>${t(tutorial?'annualProfit':'reputation')}</small><b>${tutorial?money(game.yearlyProfit()):Math.round(game.rep)}${tutorial?'':'<em>/100</em>'}</b></div></div><div class="vital"><span class="stat-icon heart">♡</span><div><small>${t('cured')}</small><b>${game.cured}<em>${game.mode==='campaign'?' / '+currentLevel().goal:''}</em></b></div></div>`);
 $('#episode-label').textContent=tutorial?t('tutorial'):game.mode==='sandbox'?t('sandbox'):`${t('level')} 0${game.level} · ${label(currentLevel().name)}`;
 patchHTML($('#time-controls'),`<span class="day-label"><span>◷</span> ${t('yearShort')}${game.year} · ${t('monthShort')}${String(game.month).padStart(2,'0')}</span>${btn('pause',paused?'▶':'Ⅱ',`time-button ${paused?'active':''}`,`title="${paused?t('play'):t('pause')}" aria-label="${paused?t('play'):t('pause')}"`)}${[1,2,3].map(n=>btn('speed',`${n}×`,`time-button ${speed===n?'active':''}`,`data-speed="${n}" aria-pressed="${speed===n}"`)).join('')}`);
 const annual=game.annualReport(),lastYear=game.financialYears.at(-1),objective=tutorial?Math.min(1,Math.max(0,annual.profit/ANNUAL_TARGET)):Math.min(1,game.cured/currentLevel().goal);
 patchHTML($('#sidebar'),`<div class="shift-heading"><span class="eyebrow">${tutorial?t('tutorial').toUpperCase():game.mode==='sandbox'?t('sandbox').toUpperCase():t('level').toUpperCase()+' 0'+game.level}</span><h1>${tutorial?t('tutorialName'):game.mode==='sandbox'?t('morning'):label(currentLevel().name)}</h1></div>
 ${tutorial?skipTutorialButton():''}
 ${guide?`<article class="guide-card"><div class="guide-kicker"><span>${t('guideClass')}</span><b>${guide.index+1} / ${GUIDE.length}</b></div><div class="guide-dots">${GUIDE.map((_,i)=>`<i class="${i<=guide.index?'done':''}"></i>`).join('')}</div><h2>${label(guide.title)}</h2><p>${label(guide.text)}</p>${guideButton(guide)}</article>`:''}
 <div class="objective-card"><div class="section-label">${t(tutorial?'annualGoal':'goal')} <span>⚑</span></div>${game.mode==='sandbox'?`<p>${t('free')}</p>`:`<div class="objective-row"><span>${t(tutorial?'profitAfterCosts':'cured')}</span><b>${tutorial?money(annual.profit):game.cured}</b></div><div class="progress-track"><i style="width:${objective*100}%"></i></div><div class="objective-row secondary"><span>${tutorial?t('annualTarget'):'★ '+t('reputation')}</span><b>${tutorial?'':Math.round(game.rep)+' / '+currentLevel().rep}</b></div>`}${tutorial?`<div class="year-track"><span>${t('year')} ${game.year}</span><b>${game.month}/12</b></div><div class="thin-progress"><i style="width:${(game.calendar%YEAR_SECONDS)/YEAR_SECONDS*100}%"></i></div>${lastYear?`<p class="last-year">${t('closedYear')} ${lastYear.year}: <b>${money(lastYear.profit)}</b></p>`:''}`:''}</div>
 <div class="flow-card"><div class="section-label">${t('patientFlow')}</div><div class="flow-total"><b>${active}</b><span>${t('patients').toLowerCase()}</span></div><div class="flow-steps">${[['reception','▤'],['diagnosis','✚'],['treatment','♡']].map(([stage,icon])=>`<div><span>${icon}</span><b>${game.patients.filter(p=>p.stage===stage).length}</b><small>${t(stage==='reception'?'registration':stage)}</small></div>`).join('')}</div><div class="waiting-summary"><span>▥ ${t('seatsOccupied')}</span><b>${game.seatStats().reserved} / ${game.seatStats().capacity}</b><small>${game.seatStats().standing} ${t('standingQueue')}</small></div><div class="health-line"><span>✧ ${t('cleanliness')}</span><b>${Math.round(game.cleanliness)}%</b></div><div class="thin-progress"><i style="width:${game.cleanliness}%"></i></div></div>
 ${game.mode==='campaign'?`<div class="story-objectives"><span class="section-label">${t('storyBriefing')}</span><p>${label(currentLevel().desc)}</p>${currentLevel().specialty?`<div class="finance-row"><span>${label(ROOMS[currentLevel().specialty].name)}</span><b>${game.curedByRoom[currentLevel().specialty]||0}/${currentLevel().specialtyGoal}</b></div><div class="finance-row"><span>${label(PROJECTS.find(p=>p.id===currentLevel().project).name)}</span><b>${game.completed.includes(currentLevel().project)?'✓':'○'}</b></div>`:''}</div>`:''}<div class="radio"><div class="section-label">${t('alerts')}</div><p>${game.logs[0]?formatLog(game.logs[0]):t('noAlerts')}</p></div>`);
 $('#clinic-open').hidden=game.admissionsOpen;
 document.body.classList.toggle('tutorial-mode',tutorial);
 const latest=game.calls.at(-1);patchHTML($('#call-banner'),latest?`<span>📣</span><div><small>${copy('Latest call','Letzter Aufruf')}</small><b>${escape(callText(latest))}</b></div>`:'');$('#call-banner').hidden=!latest;

 patchHTML($('#stage-hint'),buildType?`<span class="build-mode-dot"></span><b>${label(ROOMS[buildType].name)}</b><span>${t('buildHint')}</span>${btn('inspect','×','','aria-label="'+t('cancel')+'"')}`:`<span>↖</span> ${t(game.admissionsOpen?'selectHint':'planningHint')}`);
 if(editorRoomId!==null)patchHTML($('#stage-hint'),renderer.editor?.tool?`<b>${escape(furnitureName(renderer.editor.tool.kind))}</b><span>${copy('Click to place · R rotate · Esc cancel','Klicken zum Platzieren · R drehen · Esc abbrechen')}</span>`:`<span>↖</span> ${copy('Choose furniture from the catalog or select a placed item.','Wähle Möbel im Katalog oder klicke auf ein platziertes Stück.')}`);
 $('#stage-hint').classList.toggle('building',!!buildType||editorRoomId!==null);$('#pause-label').hidden=!paused||editorRoomId!==null;$('#zoom-value').textContent=Math.round(renderer.zoom*100)+'%';
 renderer.guideRect=editorRoomId===null&&guide?.rect?{...guide.rect,type:guide.room}:null;
 document.querySelectorAll('[data-action="pause"],[data-action="speed"],[data-action="open-clinic"],.management-tabs button,.dock-heading,.inspect-button').forEach(b=>b.disabled=editorRoomId!==null);
 document.querySelectorAll('[data-action="panel"]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.classList.remove('guide-highlight');});
 renderPanel();if(focusAttrs&&!document.contains(focused))document.querySelector(focusAttrs)?.focus({preventScroll:true});
}
function guideButton(guide){
 if(guide.furnish)return btn('edit-room',copy('Furnish this room','Raum einrichten')+' →','primary full',`data-id="${guide.roomId}"`);
 if(guide.room)return btn('guide-place',`${t('placeGuide')} · ${money(ROOMS[guide.room].cost)}`,'primary full')+btn('guide-build',t('selectRoom'),'text-button full');
 if(guide.cast)return btn('guide-hire',t('compareApplicants')+' →','primary full');
 if(guide.upgrade){const r=game.rooms.find(r=>r.type===guide.upgrade&&game.roomReady(r));return btn('guide-upgrade',`${t('upgradeGuide')} · ${money(Math.round(ROOMS[r.type].cost*.65*r.level))}`,'primary full');}
 if(guide.id==='open')return btn('open-clinic',t('openClinic')+' →','primary full');
 if(guide.id==='chart')return btn('patient-chart',t('viewChart')+' →','primary full',`data-id="${game.records[0]?.id}"`);
 if(guide.id==='profit')return btn('panel',t('viewAccounts'),'secondary full','data-panel="finances"');
 return `<div class="guide-watching">◷ ${guide.id==='cures'?`${game.cured} / 3 ${t('cured')}`:t('firstArrival')}</div>`;
}

function formatLog(l){let extra=l.extra;if(ROOMS[extra])extra=label(ROOMS[extra].name);if(PROJECTS.some(p=>p.id===extra))extra=label(PROJECTS.find(p=>p.id===extra).name);if(l.code==='paid')extra=money(Number(extra));return `${escape(t(l.code))}${extra?' · '+escape(extra):''}`;}
function panelHeader(title,kicker){return `<div class="panel-header"><div><small>${kicker}</small><h2>${title}</h2></div>${iconBtn('close-panel','×',t('close'))}</div>`;}
function renderPanel(){const el=$('#detail-panel'),scrollTop=el.querySelector('.panel-scroll')?.scrollTop||0;el.hidden=!panel;el.classList.toggle('editor-panel',panel==='room-editor');let html='';if(!panel)return;
 if(panel==='room-editor'){html=editorPanel();}
 else if(panel==='queue'){html=queuePanel();}
 else if(panel==='patients'){html=patientDirectory();}
 else if(panel==='staff'){html=renderStaffPanel(game,{view:staffView,role:recruitRole,helpers:{t,copy,label,avatar,btn,money,escape,staffStatus,panelHeader}});
 }else if(panel==='research'){html=panelHeader(t('research'),'R&D')+`<div class="panel-scroll"><p class="panel-intro">${t('noResearch')}</p>${PROJECTS.map(p=>{const done=game.completed.includes(p.id),active=game.project?.id===p.id;return `<article class="project-card"><span class="project-icon">${done?'✓':'⚗'}</span><h3>${label(p.name)}</h3><p>${label(p.desc)}</p>${active?`<div class="progress-track"><i style="width:${game.project.progress/p.time*100}%"></i></div><small>${t('researching')} · ${Math.round(game.project.progress/p.time*100)}%</small>`:btn('research',done?'✓ '+t('researched'):`${t('startResearch')} · ${money(p.cost)}`,'small-button',`data-project="${p.id}" ${done||game.project?'disabled':''}`)}</article>`;}).join('')}</div>`;
 }else if(panel==='finances'){const report=game.annualReport();html=panelHeader(t('finances'),`${t('year')} ${game.year}`)+`<div class="panel-scroll"><div class="finance-balance"><small>${t('annualProfit')}</small><b class="${report.profit<0?'negative':''}">${money(report.profit)}</b></div><p class="panel-intro">${t('profitRule')}</p>${[[t('income'),report.income],[t('expenses'),-report.expenses],[t('construction'),-report.construction],[t('profitAfterCosts'),report.profit]].map(([k,v])=>`<div class="finance-row"><span>${k}</span><b class="${v<0?'negative':'positive'}">${money(v)}</b></div>`).join('')}<div class="daily-cost"><span>${t('monthlyCost')}</span><b>${money(game.dailyCost())}</b></div><p class="panel-intro">${t('calendarRule')}</p>${game.contracts.length?`<div class="loan-card"><span>♠ ${t('loanRepayments')}</span><b>${money(game.debtRemaining())}</b><p>${t('loanRule')}</p></div>`:''}${game.modifiers.length?`<div class="loan-card"><span>${t('activeChallenges')}</span>${game.modifiers.map(m=>`<p>${t(m.kind)} · ${Math.ceil(m.endsAt-game.clock)}s</p>`).join('')}</div>`:''}<h3>${t('closedYear')}</h3>${game.financialYears.length?game.financialYears.slice().reverse().map(y=>`<div class="finance-row"><span>${t('year')} ${y.year}</span><b class="${y.profit>=ANNUAL_TARGET?'positive':''}">${money(y.profit)}</b></div>`).join(''):`<p class="panel-intro">${t('noClosedYear')}</p>`}<h3>${t('costs')}</h3>${game.ledger.map(l=>`<div class="finance-row"><span>${t('yearShort')}${l.year||1} · ${t('monthShort')}${l.day}</span><b>−${money(l.cost)}</b></div>`).join('')}</div>`;
 }else if(panel==='inspect'){if(selected?.type==='room'){const r=game.room(selected.id);if(!r){panel=null;el.hidden=true;return;}const type=ROOMS[r.type],s=game.staff.find(s=>s.id===r.staffId);html=panelHeader(label(type.name),t('roomDetails'))+`<div class="panel-scroll"><div class="room-detail-symbol" style="background:${type.color}">${type.icon}</div><p class="panel-intro">${label(type.desc)}</p>${r.renovating?`<div class="renovation-notice"><b>${copy('Clearing the room','Raum wird freigemacht')}</b><p>${copy('Current visits will finish and everyone will leave before furnishing starts.','Laufende Besuche werden beendet. Sobald alle den Raum verlassen haben, beginnt das Einrichten.')}</p></div>`:!game.roomReady(r)?`<p class="editor-warning">${copy('Unfinished room · not in service','Unfertiger Raum · noch nicht in Betrieb')}</p>`:''}${btn('edit-room',copy(r.renovating?'Waiting for the room…':'Furnish room',r.renovating?'Raum wird freigemacht…':'Raum einrichten'),'primary full',`data-id="${r.id}" ${r.renovating?'disabled':''}`)}${r.type==='waiting'?`<div class="waiting-detail"><b>${game.patients.filter(p=>p.seatRoom===r.id).length} / ${game.seats(r).length} ${t('seatsOccupied')}</b><p>${t('seatComfort')} ${Math.round((.65+(r.level-1)*.05)*100)}%</p></div>`:''}<div class="room-status" ${!type.role?'hidden':''}>${s?avatar(s):'<span>♟</span>'}<div><b>${s?escape(s.name):t('uncovered')}</b><small>${s?staffStatus(s):t('noStaff')}</small></div></div>${type.role&&!s?btn('open-staff',copy('Hire ','')+t(type.role)+copy('',' einstellen'),'primary full room-hire',`data-role="${type.role}"`):''}<div class="detail-grid">${[[t('levelWord'),r.level+'/3'],[t('queue'),game.queue(r)],[t('condition'),Math.round(r.condition)+'%'],[t('success'),type.time?Math.round(game.success(r)*100)+'%':'—']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div>${r.level<3?btn('upgrade',`${t('upgrade')} · ${money(Math.round(type.cost*.65*r.level))}`,'primary full',`data-id="${r.id}"`):`<p>${t('maxLevel')}</p>`}<h3 class="chart-section">${copy('In this room','In diesem Raum')}</h3>${roomObjects(r).map(o=>btn('object',labelObject(o,0),'object-link',`data-object="${o.id}"`)).join('')}${btn('sell',`${t('sell')} · +${money(Math.round(type.cost*.5))}`,'text-button full',`data-id="${r.id}"`)}</div>`;
 }else if(selected?.type==='object'){html=objectPanel(selected.id);}else if(selected?.type==='patient'){const record=game.record(selected.id);if(!record){panel=null;el.hidden=true;selected=null;return;}html=patientChart(record);}else{panel=null;el.hidden=true;}}
 patchHTML(el,html);el.classList.toggle('chart-panel',panel==='patients'||selected?.type==='patient');const scroller=el.querySelector('.panel-scroll');if(scroller)scroller.scrollTop=scrollTop;
}
function patientDirectory(){const records=game.records.filter(r=>patientFilter==='all'||(patientFilter==='active'?r.dischargedAt===null:r.dischargedAt!==null)).slice().reverse();return panelHeader(t('casebook'),`${game.records.length} ${t('patientCount')}`)+`<div class="patient-filters">${[['active','activePatients'],['discharged','dischargedPatients'],['all','all']].map(([value,key])=>btn('patient-filter',t(key),patientFilter===value?'active':'',`data-filter="${value}"`)).join('')}</div><div class="panel-scroll">${records.length?records.map(r=>{const live=game.patients.find(p=>p.id===r.id);return `<button class="patient-row" data-action="patient-chart" data-id="${r.id}"><span class="patient-mini"><img src="${patientPortrait(r)}" alt=""/></span><span class="patient-row-main"><small>${r.number}</small><b>${escape(r.name)}</b><span>${live?t(live.stage==='exit'?'departing':live.stage==='reception'?'checkInFirst':live.stage):t(r.outcome==='cured'?'chartCured':r.outcome==='left'?'chartLeft':'chartFailed')}</span></span><span class="patient-arrow">↗</span></button>`;}).join(''):`<p class="panel-intro">${t(game.records.length?'noMatchingPatients':'noPatients')}</p>`}</div>`;}
function patientChart(record){
 const live=game.patients.find(p=>p.id===record.id),illness=ILLNESSES.find(i=>i.id===record.illness),date=record.birthDate.split('-').reverse().join('.'),status=record.dischargedAt===null?t('chartActive'):t(record.outcome==='cured'?'chartCured':record.outcome==='left'?'chartLeft':'chartFailed');
 return panelHeader(escape(record.name),`${t('patientFile')} · ${record.number}`)+`<div class="panel-scroll"><button class="back-patients" data-action="panel" data-panel="patients">← ${t('backToPatients')}</button><div class="chart-hero"><img src="${patientPortrait(record)}" alt="${escape(record.name)}"/><div><span class="chart-number">${record.number}</span><h3>${escape(record.name)}</h3><span class="chart-status ${record.outcome||''}">${status}</span><p>${escape(t(record.priority))} · ${record.age} ${t('yearsOld')}</p></div></div><h3 class="chart-section">${t('personalDetails')}</h3><dl class="personal-grid">${[[t('dateOfBirth'),date],[t('occupation'),label(PATIENT_FACTS.occupation[record.occupation])],[t('insurance'),label(PATIENT_FACTS.insurance[record.insurance])],[t('allergies'),label(PATIENT_FACTS.allergy[record.allergy])],[t('admission'),`${t('yearShort')}${record.admittedYear} · ${t('monthShort')}${record.admittedMonth}`],[t('discharge'),record.dischargedAt===null?t('stillHere'):`${t('yearShort')}${record.timeline.at(-1)?.year} · ${t('monthShort')}${record.timeline.at(-1)?.month}`]].map(([k,v])=>`<div><dt>${k}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl><h3 class="chart-section">${t('complaint')}</h3><blockquote class="patient-quote">${record.age<16?copy('“My teddy says it is probably homework fever.”','„Mein Teddy sagt, es ist bestimmt Hausaufgabenfieber.“'):label(COMPLAINTS[record.illness])}</blockquote><div class="chart-diagnosis"><span>✚</span><div><small>${t('diagnosis')}</small><b>${record.diagnosed?label(illness.name):t('diagnosisPending')}</b></div></div>${live?`<p class="patient-location">${t(live.state==='seated'?'patientSeated':live.state==='seatTravel'?'goingToSeat':live.state==='roomExit'?'leavingRoom':live.state==='queue'?'standingQueue':['called','inside'].includes(live.state)?'calledIn':live.state==='service'?'working':'waiting')} ${live.seatRoom?`· ${t('seatNumber')} ${live.seatIndex+1}`:''}</p><div class="objective-row"><span>${t('health')}</span><b>${Math.round(live.patience)}%</b></div><div class="progress-track"><i style="width:${live.patience}%"></i></div>`:''}<h3 class="chart-section">${t('invoice')}</h3>${[[t('registrationFee'),0],[t('diagnosisCharge'),record.diagnosisCharge],[t('treatmentCharge'),record.treatmentCharge],[t('totalBilled'),record.bill]].map(([k,v])=>`<div class="finance-row"><span>${k}</span><b>${money(v)}</b></div>`).join('')}<h3 class="chart-section">${t('careTimeline')}</h3><ol class="care-timeline">${record.timeline.map(e=>`<li><small>${t('yearShort')}${e.year} · ${t('monthShort')}${e.month} · ${Math.floor(e.time%30)}s</small><b>${escape(e.code==='called'?copy('Called by the clinician','Vom Behandler aufgerufen'):t(e.code))}</b>${e.roomType?`<span>${escape(label(ROOMS[e.roomType]?.name||e.roomType))}${e.staffName?' · '+escape(e.staffName):''}</span>`:''}${e.amount?`<span>${money(e.amount)}</span>`:''}</li>`).join('')}</ol></div>`;
}

function labelObject(o,index){const kind=o.kind==='counter'&&OBJECT_INFO[o.furnitureKind]?o.furnitureKind:o.kind;return OBJECT_INFO[kind][index][lang==='de'?1:0];}
function objectPanel(id){const o=findObject(game,id);if(!o)return panelHeader(copy('Object removed','Gegenstand entfernt'),'');const r=game.room(o.roomId);return panelHeader(labelObject(o,0),label(ROOMS[r.type].name))+`<div class="panel-scroll"><div class="object-illustration">${({sofa:'🛋',chair:'🪑',toys:'🧸',door:'🚪',plant:'🪴',books:'📚',bell:'🛎',monitor:'🖥',gp:'🦆',pharmacy:'☕',sink:'🫧',toilet:'🚽'})[o.kind]||'✨'}</div><p class="object-description">${labelObject(o,1)}</p>${o.kind==='door'?btn('door',r.doorHeld?copy('Return to automatic','Wieder automatisch schließen'):copy('Hold door open','Tür offen halten'),'primary full',`data-id="${r.id}"`):''}<div class="object-facts"><span>${o.furnitureId?copy('Placed by you · move freely','Von dir platziert · kostenlos umstellen'):copy('Part of the room shell','Teil der Raumhülle')}</span><b>${copy('Room level','Raumstufe')} ${r.level}/3</b></div>${o.furnitureId?btn('edit-room',copy('Move or remove furniture','Möbel umstellen oder entfernen'),'primary full',`data-id="${r.id}"`):''}${btn('room',copy('Inspect this room','Raum ansehen'),'secondary full',`data-id="${r.id}"`)}</div>`;}
function queuePanel(){const list=game.waitingList(),called=game.patients.filter(p=>['called','inside','service'].includes(p.state)&&p.registered);return panelHeader(copy('Waiting list','Warteliste'),copy('Reception → waiting → call → care','Anmeldung → Warten → Aufruf → Behandlung'))+`<div class="panel-scroll"><p class="panel-intro">${copy('Reception creates each appointment. The next available clinician calls patients in registration order for their department.','Die Rezeption legt jeden Termin an. Der nächste freie Behandler ruft die Patienten in der Anmeldereihenfolge seiner Abteilung auf.')}</p>${called.map(p=>`<div class="queue-current">${p.state==='service'?'🩺':'📣'} <b>${escape(p.name)}</b><small>${label(ROOMS[game.room(p.targetRoom).type].name)} · ${copy(p.state==='service'?'In consultation':'Called',p.state==='service'?'In Behandlung':'Aufgerufen')}</small></div>`).join('')}${game.rooms.filter(r=>ROOMS[r.type].role&&!game.staffReady(game.staff.find(s=>s.id===r.staffId))).map(r=>{const s=game.staff.find(s=>s.id===r.staffId);return `<p class="queue-current"><b>${label(ROOMS[r.type].name)} · ${r.id}</b><small>${s?staffStatus(s):copy('No staff assigned','Kein Personal zugeteilt')}</small></p>`;}).join('')}<h3 class="chart-section">${list.length} ${copy('waiting appointments','wartende Termine')}</h3>${list.map((p,i)=>`<button class="queue-row" data-action="patient-chart" data-id="${p.id}"><span>${i+1}</span><div><b>${p.child?'🧸 ':''}${escape(p.name)}</b><small>${label(ROOMS[game.need(p)].name)} · ${copy(p.state==='seated'?'Seated':'Waiting',p.state==='seated'?'Sitzt':'Wartet')}</small></div><span>↗</span></button>`).join('')||`<p class="panel-intro">${copy('No registered appointments waiting.','Keine angemeldeten Termine warten.')}</p>`}${btn('panel',copy('All patient records','Alle Patientenakten'),'secondary full','data-panel="patients"')}</div>`;}

let previousFocus=null;
function openModal(type,extra){voice.suspend(true);previousFocus=menuOpen?$('#game-menu [data-action="game-menu"]'):document.activeElement;menuOpen=false;renderMenu();modal={type,extra};renderModal();}
function closeModal(){modal=null;$('#modal-root').innerHTML='';document.querySelector('.topbar').inert=false;document.querySelector('.workbar').inert=false;document.querySelector('.game-shell').inert=false;(document.contains(previousFocus)?previousFocus:$('#game-menu [data-action="game-menu"]'))?.focus();}
function renderModal(){if(!modal)return;let html='',wide=false;const type=modal.type;
 if(type==='welcome'){html=`<div class="modal-body"><span class="eyebrow">${game.mode==='campaign'?t('campaign'):t('sandbox')}</span><h2>${game.mode==='campaign'?label(currentLevel().name):t('emptyStartTitle')}</h2><p class="modal-subtitle">${game.mode==='campaign'?label(currentLevel().desc):t('sandboxDesc')}</p><ol class="start-steps">${[1,2,3].map(i=>`<li><b>${t('startStep'+i)}</b><span>${t('startStep'+i+'Text')}</span></li>`).join('')}</ol><p class="start-goal">${t('startFloorHint')}</p>${btn('close-modal',t('startBuilding')+' →','primary full')}</div>`;
 }else if(type==='help'){wide=true;html=`<div class="modal-body"><span class="eyebrow">${lang==='de'?'DIE EINWEISUNG, DIE EINE E-MAIL HÄTTE SEIN KÖNNEN':'THE ORIENTATION THAT COULD HAVE BEEN AN EMAIL'}</span><h2>${t('help')}</h2><p class="modal-subtitle">${t('guideSubtitle')}</p><div class="guide-grid">${[1,2,3,4,5].map(i=>`<div><span class="guide-number">0${i}</span><h3>${t('guide'+i)}</h3><p>${t('guide'+i+'Text')}</p></div>`).join('')}</div><p class="keyboard-guide">${t('controls')}</p>${btn('close-modal',t('gotIt')+' →','primary')}</div>`;
 }else if(type==='episodes'){wide=true;html=`<div class="modal-body"><span class="eyebrow">FUNNY HOSPITAL</span><h2>${t('selectEpisode')}</h2><div class="tutorial-episode-card"><div><span class="eyebrow">${t('orientation')}</span><h3>${t('tutorial')}</h3><p>${t('tutorialIntro')}</p></div>${btn('new-game',t('startTutorial')+' →','primary','data-mode="tutorial" data-level="1"')}</div><div class="episode-grid">${LEVELS.map(l=>{const locked=l.id>1&&!progress.includes(l.id-1);return `<article class="episode-card ${locked?'locked':''}"><span class="episode-number">0${l.id}</span><span class="eyebrow">${t('level')} ${l.id} ${progress.includes(l.id)?'★':''}</span><h3>${label(l.name)}</h3><p>${label(l.desc)}</p>${btn('new-game',locked?'⌑ '+t('locked'):t('start')+' →','small-button',`data-level="${l.id}" data-mode="campaign" ${locked?'disabled':''}`)}</article>`;}).join('')}</div><div class="sandbox-card"><div><h3>∞ ${t('sandbox')}</h3><p>${t('sandboxDesc')}</p></div>${btn('new-game',t('start')+' →','primary','data-mode="sandbox" data-level="1"')}</div></div>`;
 }else if(type==='load'){const saved=modal.extra.game;html=`<div class="modal-body"><span class="eyebrow">FUNNY HOSPITAL</span><h2>${copy('Load session','Sitzung laden')}</h2>${saved?`<p class="modal-subtitle">${copy('Your latest local save, including autosaves. Loading replaces the current session and pauses the clinic.','Dein letzter lokaler Spielstand, einschließlich automatischer Speicherungen. Laden ersetzt die aktuelle Sitzung und pausiert die Klinik.')}</p><div class="detail-grid">${[[copy('Game mode','Spielmodus'),t(saved.mode==='tutorial'?'tutorial':saved.mode==='sandbox'?'sandbox':'campaign')],[copy('Date','Zeitpunkt'),`${t('year')} ${saved.year} · ${t('month')} ${saved.month}`],[t('rooms'),saved.rooms.length],[t('cash'),money(saved.cash)]].map(([key,value])=>`<div><small>${key}</small><b>${value}</b></div>`).join('')}</div>${btn('load-confirm',copy('Load saved session','Gespeicherte Sitzung laden'),'primary full')}`:`<p class="modal-subtitle">${t(modal.extra.source?'badSave':'noSave')}</p>`}<div class="save-buttons">${btn('import','↑ '+t('import'),'secondary')}${btn('close-modal',t('cancel'),'secondary')}</div></div>`;
 }else if(type==='language'){html=`<div class="modal-body"><span class="eyebrow">FUNNY HOSPITAL</span><h2>${t('language')}</h2>${languageOptions()}</div>`;
 }else if(type==='audio-options'){html=`<div class="modal-body"><span class="eyebrow">FUNNY HOSPITAL</span><h2>${t('sound')}</h2>${audioOptions()}</div>`;
 }else if(type==='settings'){html=`<div class="modal-body"><span class="eyebrow">FUNNY HOSPITAL</span><h2>${t('settings')}</h2>${languageOptions()}${audioOptions()}<p class="panel-intro">${t('autoSave')}</p><div class="save-buttons">${btn('export','↓ '+t('export'),'secondary')}${btn('import','↑ '+t('import'),'secondary')}</div>${btn('episodes',t('newGame'),'text-button full')}${btn('delete-save',t('deleteSave'),'text-button full danger')}<p class="credits">${t('credits')}</p><a class="source-link" href="https://github.com/MarcelWeissgerberIT/scrubssitel" target="_blank" rel="noopener">GitHub ↗</a></div>`;
 }else if(type==='event'){const ev=EVENTS.find(e=>e.id===game.event);if(!ev){closeModal();return;}html=`<div class="modal-body event-body"><span class="eyebrow">${t('event')}</span><div class="event-emoji">${{coffee:'☕',review:'★',grant:'✉',rush:'⚡',mafia:'♠',printer:'▤',inspection:'♧',influencer:'✦'}[ev.id]}</div><h2>${label(ev.name)}</h2><p>${label(ev.text)}</p><div class="event-choices">${ev.choices.map((c,i)=>btn('event-choice',label(c.label),'secondary',`data-choice="${i}" ${c.cost>0&&game.cash<c.cost?'disabled':''}`)).join('')}</div></div>`;
 }else if(type==='tutorial-win'){html=`<div class="modal-body win-body"><span class="win-icon">★</span><h2>${t('guideFinished')}</h2><p>${t('tutorialWin')}</p><div class="finance-balance"><small>${t('bestYear')}</small><b>${money(Math.max(...game.financialYears.map(y=>y.profit)))}</b></div>${btn('close-modal',t('keepPlaying'),'primary full')}${btn('episodes',t('selectEpisode'),'text-button full')}</div>`;
 }else if(type==='win'||type==='over'){html=`<div class="modal-body win-body"><span class="win-icon">${type==='win'?'★':'☂'}</span><span class="eyebrow">${t('level')} 0${game.level}</span><h2>${t(type==='win'?'win':'gameOver')}</h2><p>${t(type==='win'?'winText':'gameOverText')}</p><div class="win-stats"><span><b>${game.cured}</b>${t('cured')}</span><span><b>${Math.round(game.rep)}</b>${t('reputation')}</span><span><b>${money(game.cash)}</b>${t('cash')}</span></div>${type==='win'?(game.level<3?btn('next',t('nextEpisode')+' →','primary full'):`<p>${t('completedCampaign')}</p>`)+btn('close-modal',t('keepPlaying'),'text-button full'):btn('retry',t('retry'),'primary full')}</div>`;
 }else if(type==='confirm'){html=`<div class="modal-body"><h2>${t(modal.extra.title)}</h2><p>${t(modal.extra.text)}</p><div class="modal-actions">${btn('confirm',t('yes'),'primary')}${btn('close-modal',t('cancel'),'secondary')}</div></div>`;}
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''} ${type==='welcome'?'setup-modal':''}" role="dialog" aria-modal="true" aria-label="${escape(type==='welcome'?t('guideTitle'):type==='event'?t('event'):t(type==='episodes'?'selectEpisode':type==='over'?'gameOver':type==='audio-options'?'sound':type==='load'?'loadSession':type))}">${!['welcome','event','over','win','confirm'].includes(type)?iconBtn('close-modal','×',t('close')):''}${html}</section></div>`;
 for(const selector of ['.topbar','.workbar','.game-shell'])$(selector).inert=true;
 requestAnimationFrame(()=>$('#modal-root button:not(:disabled)')?.focus());
 $('#language-select')?.addEventListener('change',e=>{prefs.lang=e.target.value;persistPrefs();changeLanguage(prefs.lang==='auto'?detectLanguage():prefs.lang);});
}
function confirm(title,text,action){confirmAction=action;openModal('confirm',{title,text});}
function openLoad(){readStoredClinic();openModal('load',{game:savedGame,source:savedSource});}
function resumeGame(restored=null,pauseAfterLoad=false){
 if(!restored){readStoredClinic();restored=savedGame;}
 if(!restored){renderUI();notify(t(savedSource?'badSave':'noSave'),true);return;}
 clearEditor();game=restored;startScreen=false;savedGame=null;savedSource=null;
 lastCured=game.cured;winShown=game.won;overShown=false;paused=pauseAfterLoad;speed=1;panel=null;selected=null;buildType=null;
 renderer.selected=null;renderer.buildType=null;renderer.drag=null;accumulator=0;lastSave=performance.now();autosaveEnabled=true;
 voice.reset(game.callSerial);closeModal();renderUI();renderer.reset();renderer.resize();
 if(!pauseAfterLoad&&game.admissionsOpen&&prefs.announcements!==false)voice.activate(lang);
}

function newGame(mode,level){clearEditor();accumulator=0;startScreen=false;savedGame=null;savedSource=null;game=new Game({mode,level});voice.reset(0);lastCured=game.cured;paused=false;speed=1;selected=null;panel=null;buildType=null;winShown=false;overShown=false;renderer.selected=null;renderer.buildType=null;renderer.reset();autosaveEnabled=true;closeModal();save(false);renderUI();renderer.resize();if(mode!=='tutorial')openModal('welcome');}
function changeLanguage(next){voice.setLanguage(next);lang=next;t=translator(lang);const oldZoom=renderer.zoom,oldPan=renderer.pan,oldEditor=renderer.editor;const oldModal=modal;shell();renderer.zoom=oldZoom;renderer.pan=oldPan;renderer.selected=selected;renderer.buildType=buildType;renderer.editor=oldEditor;modal=oldModal;renderUI();if(modal)renderModal();}
async function importSave(e){const input=e.target;try{const file=input.files[0];if(!file)return;if(file.size>25000000)throw Error('Too large');const data=JSON.parse(await file.text());const restored=Game.restore(data.game||data);clearEditor();startScreen=false;savedGame=null;savedSource=null;game=restored;voice.reset(game.callSerial);lastCured=game.cured;if(data.progress&&Array.isArray(data.progress))progress=data.progress.filter(x=>[1,2,3,'tutorial'].includes(x));selected=null;panel=null;renderer.selected=null;buildType=null;renderer.buildType=null;paused=true;winShown=game.won;overShown=false;autosaveEnabled=true;closeModal();save(false);renderUI();renderer.resize();notify(t('imported'));}catch{notify(t('badSave'),true);}input.value='';}
function exportSave(){if(startScreen){readStoredClinic();if(!savedSource){renderUI();notify(t('noSave'));return;}}const source=startScreen?savedGame:game;const blob=new Blob([source?JSON.stringify({game:source.snapshot(),progress},null,2):savedSource||'{}'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`funny-hospital-day-${source?.day||1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('#app').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(modal&&!b.closest('#modal-root'))return;
 const menuAction=!!b.closest('#game-menu');
 if(menuAction&&['build','open-staff','panel','inspect'].includes(a)&&editorRoomId!==null)leaveRoomEditor();
 if(editorRoomId!==null&&['toggle-build','guide-place','guide-build','guide-hire','guide-upgrade','open-clinic','panel','build','inspect','pause','speed'].includes(a))return;
 if(menuAction&&!['game-menu','menu-section','menu-close'].includes(a)){menuOpen=false;renderMenu();}

 switch(a){case 'game-menu':menuOpen=!menuOpen;renderMenu();$('#game-menu '+(menuOpen?'.game-menu-category.active':'[data-action="game-menu"]'))?.focus();break;case 'menu-close':menuOpen=false;renderMenu();$('#game-menu [data-action="game-menu"]')?.focus();break;case 'menu-section':menuSection=b.dataset.section;renderMenu();break;case 'open-staff':openStaff(b.dataset.role,b.dataset.view);break;case 'staff-view':staffView=b.dataset.view==='team'?'team':'hire';renderUI();resetPanelScroll();break;case 'language':openModal('language');break;case 'audio-options':openModal('audio-options');break;case 'skip-tutorial':if(game.mode==='tutorial'){game.skipTutorial();winShown=false;if(autosaveEnabled)save(false);renderUI();notify(copy('Tutorial skipped. Your clinic continues in free play.','Tutorial übersprungen. Deine Klinik läuft im freien Spiel weiter.'));}break;case 'edit-room':requestRoomEditor(+b.dataset.id);break;case 'editor-close':leaveRoomEditor();break;case 'editor-finish':{const response=game.finishRoom(editorRoomId);if(result(response,copy('Room ready','Raum ist bereit')))leaveRoomEditor();break;}case 'furniture-buy':editorItemId=null;renderer.setFurnitureTool(b.dataset.kind);renderUI();renderer.canvas.focus({preventScroll:true});break;case 'furniture-select':selectFurniture(b.dataset.furniture);break;case 'furniture-move':{const item=game.room(editorRoomId)?.furniture.find(f=>f.id===editorItemId);if(item){renderer.setFurnitureTool(item.kind,item);renderUI();renderer.canvas.focus({preventScroll:true});}break;}case 'furniture-rotate':renderer.rotateFurnitureTool();renderer.canvas.focus({preventScroll:true});break;case 'furniture-cancel':renderer.cancelFurnitureTool();renderUI();break;case 'furniture-remove':{const response=game.removeFurniture(editorRoomId,editorItemId);if(result(response)){editorItemId=null;renderer.editor.itemId=null;renderer.cancelFurnitureTool();if(autosaveEnabled)save(false);renderUI();}break;}case 'furniture-template':{const response=game.autoFurnish(editorRoomId);if(result(response)){renderer.cancelFurnitureTool();if(autosaveEnabled)save(false);renderUI();}break;}case 'voice':if(voice.enabled&&voice.ready){prefs.announcements=false;voice.mute();}else{prefs.announcements=true;voice.activate(lang);}persistPrefs();renderUI();if(modal)renderModal();break;case 'object':selected={type:'object',id:b.dataset.object};renderer.selected=selected;panel='inspect';renderUI();break;case 'door':game.toggleDoor(+b.dataset.id);renderUI();break;case 'room':selected={type:'room',id:+b.dataset.id};renderer.selected=selected;panel='inspect';renderUI();break;case 'pause':paused=!paused;renderUI();break;case 'speed':speed=+b.dataset.speed;paused=false;renderUI();break;case 'save':autosaveEnabled=true;save();renderMenu();break;case 'load-game':openLoad();break;case 'load-confirm':{const restored=modal?.type==='load'&&modal.extra.game;if(restored){resumeGame(restored,true);notify(copy('Session loaded · paused','Sitzung geladen · pausiert'));}break;}case 'help':openModal('help');break;case 'settings':openModal('settings');break;case 'episodes':openModal('episodes');break;case 'close-modal':if(!game.event&&!game.over)closeModal();break;case 'switch-language':prefs.lang=lang==='en'?'de':'en';persistPrefs();changeLanguage(prefs.lang);break;case 'patient-filter':patientFilter=b.dataset.filter;renderUI();break;case 'patient-chart':selected={type:'patient',id:+b.dataset.id};game.readChart(selected.id);renderer.selected=selected;panel='inspect';renderUI();break;case 'guide-place':{const guide=game.guide();if(guide?.room){const response=game.addRoom(guide.room,guide.rect);if(result(response,t('built'))){enterRoomEditor(response.room);if(autosaveEnabled)save(false);}}break;}case 'guide-build':{const g=game.guide();if(g?.room){buildType=g.room;renderer.buildType=g.room;renderer.reset();renderer.canvas.focus();renderUI();}break;}case 'guide-hire':{const g=game.guide();if(g?.cast){openStaff(CAST.find(c=>c.id===g.cast).role);}break;}case 'guide-upgrade':{const g=game.guide(),r=game.rooms.find(r=>r.type===g?.upgrade&&game.roomReady(r));if(r)result(game.upgrade(r.id),t('upgraded'));break;}case 'open-clinic':if(result(game.openClinic(),t('clinicOpened'))&&prefs.announcements!==false)voice.activate(lang);break;case 'panel':buildType=null;renderer.buildType=null;selected=null;renderer.selected=null;panel=panel===b.dataset.panel?null:b.dataset.panel;renderUI();break;case 'close-panel':panel=null;selected=null;renderer.selected=null;renderUI();break;
 case 'build':buildType=buildType===b.dataset.type?null:b.dataset.type;renderer.buildType=buildType;panel=null;selected=null;renderer.selected=null;renderUI();break;case 'inspect':buildType=null;renderer.buildType=null;renderer.drag=null;renderUI();break;case 'recruit-role':recruitRole=b.dataset.role;staffView='hire';renderUI();resetPanelScroll();break;case 'hire-applicant':result(game.hireApplicant(b.dataset.applicant),t('hireDone'));break;case 'refresh-applicants':result(game.refreshApplicants(),t('newApplicants'));break;case 'staff-break':game.requestBreak(+b.dataset.id);renderUI();break;case 'dismiss-staff':confirm('dismiss','dismissText',()=>result(game.dismiss(+b.dataset.id)));break;case 'upgrade':result(game.upgrade(+b.dataset.id),t('upgraded'));break;case 'sell':confirm('confirmSell','confirmSellText',()=>{if(result(game.sell(+b.dataset.id))){selected=null;panel=null;renderer.selected=null;}});break;case 'research':result(game.startResearch(b.dataset.project));break;
 case 'zoom-in':renderer.setZoom(renderer.zoom+.15);renderUI();break;case 'zoom-out':renderer.setZoom(renderer.zoom-.15);renderUI();break;case 'center':renderer.reset();renderUI();break;case 'fullscreen':if(!document.fullscreenElement){document.documentElement.requestFullscreen?.().catch(()=>{});}else document.exitFullscreen?.();break;
 case 'new-game':{const mode=b.dataset.mode,level=+b.dataset.level;if(startScreen)readStoredClinic();if(startScreen&&!savedSource)newGame(mode,level);else confirm('confirmNew','confirmNewText',()=>newGame(mode,level));break;}case 'resume-game':resumeGame();break;case 'confirm':{const action=confirmAction;closeModal();action?.();renderUI();break;}case 'next':newGame('campaign',Math.min(3,game.level+1));break;case 'retry':newGame(game.mode,game.level);break;
 case 'sound':prefs.sound=!prefs.sound;persistPrefs();chime();renderModal();break;case 'export':exportSave();break;case 'import':$('#import-file').click();break;case 'delete-save':confirm('deleteSave','deleteSaveText',()=>{try{localStorage.removeItem('scrubssitel-save');localStorage.removeItem('scrubssitel-progress');progress=[];autosaveEnabled=false;notify(t('deleted'));}catch{notify(t('saveFailed'),true);}});break;
 case 'event-choice':if(result(game.resolveEvent(+b.dataset.choice))){closeModal();if(autosaveEnabled)save(false);}break;
 }});
document.addEventListener('keydown',e=>{if(modal){if(e.key==='Tab'){const items=[...document.querySelectorAll('#modal-root button:not(:disabled), #modal-root select, #modal-root a')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'&&!['event','over','win','welcome'].includes(modal.type))closeModal();return;}if(e.key==='Escape'&&menuOpen){e.preventDefault();menuOpen=false;renderMenu();$('#game-menu [data-action="game-menu"]')?.focus();return;}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)&&e.key!=='Escape')return;if(e.key.toLowerCase()==='m'){e.preventDefault();menuOpen=!menuOpen;renderMenu();$('#game-menu '+(menuOpen?'.game-menu-category.active':'[data-action="game-menu"]'))?.focus();return;}if(startScreen)return;if(e.key.toLowerCase()==='b'){menuSection='rooms';menuOpen=true;renderMenu();$('#game-menu .game-menu-category.active')?.focus();return;}if(document.activeElement?.tagName==='BUTTON'&&e.key!=='Escape')return;if(editorRoomId!==null){if(e.key==='Escape'){e.preventDefault();if(renderer.editor?.tool){renderer.cancelFurnitureTool();renderUI();}else leaveRoomEditor();}else if(e.key.toLowerCase()==='r'){e.preventDefault();renderer.rotateFurnitureTool();}else if(e.code==='Space')e.preventDefault();return;}if(e.code==='Space'){e.preventDefault();paused=!paused;renderUI();}if(['1','2','3'].includes(e.key)){speed=+e.key;paused=false;renderUI();}if(e.key==='Escape'){buildType=null;renderer.buildType=null;renderer.drag=null;panel=null;renderUI();}});
window.addEventListener('beforeunload',()=>{if(autosaveEnabled)save(false);});
document.addEventListener('visibilitychange',()=>{voice.suspend(document.hidden||paused||!!modal||editorRoomId!==null);if(document.hidden&&autosaveEnabled)save(false);});
shell();renderer.resize();
let last=performance.now(),accumulator=0,lastUI=0,lastCured=game.cured,animationTime=0;
function frame(now){voice.suspend(paused||!!modal||document.hidden||game.over||editorRoomId!==null);const elapsed=Math.min((now-last)/1000,.25);last=now;
 if(!startScreen&&!paused&&!modal&&!document.hidden&&!game.over&&editorRoomId===null){accumulator+=elapsed*speed;while(accumulator>=.05){renderer.captureStep(game);game.update(.05);accumulator-=.05;if(game.event||game.over)break;}}
 if(!paused&&!modal&&!document.hidden&&editorRoomId===null)animationTime+=elapsed*speed;renderer.draw(game,animationTime,Math.min(1,accumulator/.05));
 voice.accept(game.calls.map(c=>({...c,text:callText(c)})),c=>game.clock-c.time<18&&game.patients.some(p=>p.id===c.patientId&&p.targetRoom===c.roomId&&['called','inside'].includes(p.state)));
 if(game.cured>lastCured){chime('cure');lastCured=game.cured;}
 if(game.event&&!modal)openModal('event');
 if(game.won&&!winShown&&!modal){winShown=true;const key=game.mode==='tutorial'?'tutorial':game.level;if(!progress.includes(key))progress.push(key);if(autosaveEnabled)save(false);openModal(game.mode==='tutorial'?'tutorial-win':'win');}
 if(game.over&&!overShown){overShown=true;openModal('over');if(autosaveEnabled)save(false);}
 if(now-lastUI>500){if(pendingEditRoomId!==null&&!modal){const room=game.room(pendingEditRoomId);if(!room)pendingEditRoomId=null;else{const response=game.beginRoomEdit(room.id);if(!response.pending&&!response.error)enterRoomEditor(response.room||room);}}renderUI();lastUI=now;}
 if(autosaveEnabled&&now-lastSave>20000){save(false);lastSave=now;}
 requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
